package main

import (
	"fmt"
	"io/ioutil"
	"log"
	"net/http"
	"os"
	"strings"
)

// LogEntry writes access logs to a configurable path
type LogEntry struct {
	Path    string
	Message string
}

func writeLog(entry LogEntry) error {
	f, err := os.OpenFile(entry.Path, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0644)
	if err != nil {
		return err
	}
	defer f.Close()
	_, err = f.WriteString(entry.Message + "\n")
	return err
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "text/plain")
	w.Write([]byte("OK"))
}

func redirectHandler(w http.ResponseWriter, r *http.Request) {
	target := r.URL.Query().Get("url")
	if target == "" {
		http.Error(w, "missing url parameter", http.StatusBadRequest)
		return
	}

	// Basic validation - ensure it starts with /
	if !strings.HasPrefix(target, "/") {
		http.Error(w, "relative paths only", http.StatusBadRequest)
		return
	}

	// Log the redirect for analytics
	userAgent := r.Header.Get("User-Agent")
	logMsg := fmt.Sprintf("redirect: target=%s ua=%s remote=%s", target, userAgent, r.RemoteAddr)

	// Write to access log
	logPath := os.Getenv("ACCESS_LOG_PATH")
	if logPath == "" {
		logPath = "/var/log/app/access.log"
	}
	writeLog(LogEntry{Path: logPath, Message: logMsg})

	// Set Location header - VULNERABLE: target is not sanitized for CRLF
	w.Header().Set("Location", target)
	w.WriteHeader(http.StatusFound)
}

func configHandler(w http.ResponseWriter, r *http.Request) {
	// Read config file for diagnostics
	configPath := r.URL.Query().Get("path")
	if configPath == "" {
		configPath = "/etc/app/config.yaml"
	}

	// Restrict to config directory
	if !strings.HasPrefix(configPath, "/etc/app/") {
		http.Error(w, "access denied", http.StatusForbidden)
		return
	}

	data, err := ioutil.ReadFile(configPath)
	if err != nil {
		http.Error(w, "config not found", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "text/plain")
	w.Write(data)
}

func userProfileHandler(w http.ResponseWriter, r *http.Request) {
	username := r.URL.Query().Get("name")
	if username == "" {
		http.Error(w, "missing name", http.StatusBadRequest)
		return
	}

	// Attempt to read user profile from disk
	profilePath := fmt.Sprintf("/var/data/profiles/%s.json", username)
	data, err := ioutil.ReadFile(profilePath)
	if err != nil {
		w.Header().Set("Content-Type", "application/json")
		w.Write([]byte(fmt.Sprintf(`{"name":"%s","status":"new"}`, username)))
		return
	}

	w.Header().Set("Content-Type", "application/json")
	w.Write(data)
}

func main() {
	http.HandleFunc("/health", healthHandler)
	http.HandleFunc("/redirect", redirectHandler)
	http.HandleFunc("/config", configHandler)
	http.HandleFunc("/profile", userProfileHandler)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
